import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"已知问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/KNOWN_ISSUES.md","filePath":"zh/root/KNOWN_ISSUES.md"}'),i={name:"zh/root/KNOWN_ISSUES.md"};function r(c,t,s,n,l,u){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="已知问题" tabindex="-1">已知问题 <a class="header-anchor" href="#已知问题" aria-label="Permalink to &quot;已知问题&quot;">​</a></h1><p>已知缺陷及其状态的滚动记录。2.0.0 发布带着下面十七条问题 （由 2.0.0 postcheck 发现，<code>audit/2.0.0-postcheck/</code> 在私有 镜像中）；<strong>全部十七条在 2.1.0 修复</strong>。v1 时代的问题档案 在 <code>docs/archive/KNOWN_ISSUES.md</code>。</p><h2 id="_2-0-0-问题-全部在-2-1-0-修复" tabindex="-1">2.0.0 问题 - 全部在 2.1.0 修复 <a class="header-anchor" href="#_2-0-0-问题-全部在-2-1-0-修复" aria-label="Permalink to &quot;2.0.0 问题 - 全部在 2.1.0 修复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>类别</th><th>问题</th><th>2.1.0 修复方式</th></tr></thead><tbody><tr><td>P-01</td><td>P0 CI/发布门禁</td><td>v2.0.0 的发布代码在 CI runner 上编译失败（tui_core.c 对端口 0x3F8/0x3FD 使用 imm8 &quot;Nd&quot; 约束的 in/out——端口 &gt;= 0x100 必须经 DX）。全部 15 次 v2.0.0 CI 运行都是红的；发布以本地绿/CI 红出厂，未声明。</td><td>端口 I/O 强制经 <code>%dx</code>（&quot;d&quot; 约束、u16 操作数）；加上途中发现并修复的另外两个 CI 环境陷阱：runner 的 GRUB（2.12+）丢掉了 <code>efi_uga.mod</code>（模块清单现在对照已安装的 GRUB 过滤），以及 gcc &gt;= 15 默认 C23，<code>typedef u8 bool</code> 与原生 <code>_Bool</code> 关键字冲突（core/types.h 在 C23 下保留编译器的 bool，gnu11 下用 u8）。CI 重新变绿并成为硬发布门禁。</td></tr><tr><td>P-02</td><td>P1 发布数据</td><td>发布说明的数字自相矛盾（&quot;251 条命令中的 134 条已迁移&quot; vs &quot;251 = 99+133+19&quot;；99+134+19=252）。</td><td>2.1.0 发布说明使用自洽的账目：251 = 99 L0 + 133 SVC + 19 内建；v1 基线 233，全部映射（INTERFACES.md Part 1c）。</td></tr><tr><td>P-03</td><td>P1 兼容性契约</td><td>v1-&gt;v2 映射表为 233 条命令的基线只有 231 行：<code>health export</code> 和 <code>health watch</code> 被一个无空格解析正则静默丢弃。</td><td>生成器已修复；Part 1c 映射全部 233 条，零 MISSING。</td></tr><tr><td>P-04</td><td>P1 接口真相</td><td>没有逐条目的 162-&gt;158 对照；&quot;register 类接口已消失&quot;是过度概括。</td><td>INTERFACES.md Part 2c：基于完整 v1 Part 2 真相的逐条目表（278 条声明：267 公开、6 内化、5 消失）；interfaces.json 报告当前的 17/158 面及 v1 命运字段。</td></tr><tr><td>P-05</td><td>P1 删除</td><td>没有删除登记表；两处真实删除从未声明。</td><td>INTERFACES.md Part 2d 声明全部五处删除（init/probe 管线）及其验证过的 v2 替代；register 类的陈述精确化。</td></tr><tr><td>P-06</td><td>P1 文档</td><td>ARCHITECTURE.md 描述的是 v1 树（kernel/、userprogs/、233、53 个系统调用、162、&quot;默认启动进 oc&gt;&quot;）。</td><td>按真实树重写（两个环、54 个系统调用、17/158、ush 默认入口），EN + zh 镜像。</td></tr><tr><td>P-07</td><td>P1 流程文档</td><td>versioning.md（无 +21 偏移）、process.md（WP- tag、v1 门禁）、dev/build.md、dev/e2e-suites.md、manual/index.md、BUILDING.md L141 全是 v1 时代内容。</td><td>全部更新到 v2 现实（v-tag、六套件矩阵 + L1 逐应用门禁、+21 偏移成文、当前数字）。</td></tr><tr><td>P-08</td><td>P1 测试覆盖</td><td>没有逐应用 L1 测试；v1 的 28 项用户程序回归测试组缺席 2.0.0 矩阵。</td><td>2.1.0 矩阵新增 L1 逐应用记录（ush + 每个内嵌程序被执行）；见 docs/dev/e2e-suites.md。</td></tr><tr><td>P-09</td><td>P1 注释</td><td>Makefile 注释声称 tui/chinese &quot;已重写为 L1 Ring-3 应用&quot;，而两棵树仍编译进内核。</td><td>注释已更正（tui/chinese 保持 L0 驻留；l1apps/ 只装 ush + 内嵌程序）。</td></tr><tr><td>P-10</td><td>P2 网站数据</td><td>site-data.js 的 stats.lines=130,011 vs 真实 130,495；update_website.sh 把过期统计块原样前移。</td><td>update_website.sh 从 docs/data/*.json 重新生成统计块；站点数字始终与数据文件一致。</td></tr><tr><td>P-11</td><td>P2 资产</td><td>公开仓库 main 树不含发布 ISO/SRC（只有私有镜像 + gh-pages 有），与发布说明矛盾。</td><td>2.1.0 资产提交进公开 main（website/public/downloads/），与 Release/gh-pages 逐字节一致。</td></tr><tr><td>P-12</td><td>P2 资产</td><td>website/public/update*.json 仍携带 WP-13/build-259 清单（顶层数对是 2.0.0/302）。</td><td>update_website.sh 逐字节写入两份副本（顶层 + public/）。</td></tr><tr><td>P-13</td><td>P2 证据</td><td>2.0.0 证据 README 引用的五份套件日志在两个仓库中都不存在；asset_hashes.txt 里的 SRC 文件名是错的。</td><td>五份日志是 2.1.0 运行重新生成的真实文件（evidence/），asset_hashes.txt 命名实际发布的文件。</td></tr><tr><td>P-14</td><td>P2 计数口径</td><td>commands.json 的 count_l1_svc=133 vs 真实的 142 行 ush SVC 表——9 个双宿主名被静默归给 L0；interfaces.json 仍携带 v1 的 162 官方计数。</td><td>口径在 commands.json + INTERFACES.md Part 1b 中精确陈述（142 行、9 个双宿主、账目 251 不变）；interfaces.json 报告 17/158。</td></tr><tr><td>P-15</td><td>P2 文档</td><td>docs/manual/commands 是 v1 产物（234 页，&quot;Registered in: shell/...&quot; 路径）；23 条 v2 新命令没有页面。</td><td>完全重新生成：251 页（EN + zh），真实 v2 归属、幽灵页清除、帮助提示取自 l1svc_defs.h。</td></tr><tr><td>P-16</td><td>P2 治理</td><td>私有镜像的 SYNC-RULES.md 描述的树布局已不存在；2.0.0 的过程日志不在仓库里。</td><td>SYNC-RULES.md 按当前布局重写；过程记录延伸到 2.1.0（都在私有镜像中）。</td></tr><tr><td>P-17</td><td>P3 文本缺陷</td><td>docs/dev/index.md 一条链接被标记为 &quot;ost-tests (missing h)&quot;；wp14_site_v2 证据目录名；379 文件口径注记。</td><td>该链接缺陷查明是误报（字节级检查显示 <code>[host-tests]</code> 一直是对的——postcheck 证据中的显示伪影吃掉了 <code>[h</code> 序列；已如实记录）。证据目录命名在 2.1.0 更正，文件数口径写入数据注记。</td></tr></tbody></table><h2 id="_2-1-0-遗留问题-全部在-2-2-0-修复" tabindex="-1">2.1.0 遗留问题 - 全部在 2.2.0 修复 <a class="header-anchor" href="#_2-1-0-遗留问题-全部在-2-2-0-修复" aria-label="Permalink to &quot;2.1.0 遗留问题 - 全部在 2.2.0 修复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>类别</th><th>问题</th><th>2.2.0 修复方式</th></tr></thead><tbody><tr><td>O-01</td><td>内核</td><td>wp10_tui 套件在收尾的 checkupdate SVC 轮之后 #DF（2.0.0 与 2.1.0 相同；已在 2.1.0 交付卷宗中声明）。根因：最深的真实内核调用链（SYS_L1SVC -&gt; ota_update_check -&gt; http_get_body 6000 B 帧 -&gt; net_tls_https_get 2144 -&gt; tls13_do_handshake -&gt; crypto_x509_verify_chain 1872 -&gt; crypto_rsa_verify_pss 2704 -&gt; crypto_bn_mod_exp 4160 -&gt; mont_mul 1200 -&gt; mont_redc 1856；-fstack-usage 合计约 23.6 KB）加上同栈上的 timer/e1000 IRQ 嵌套，超出了 20 KiB 的可用 kthread 栈（24 KiB 分配减去未映射的守卫页）。记录到的崩溃：rip=crypto_bn_mont_redc+0x2A，rsp 低于栈顶 20,880 B、落在守卫页内。</td><td>OC_KTHREAD_STACK_PAGES 6 -&gt; 10（40 KiB 窗口 / 36 KiB 可用，比实测最坏链 + IRQ 嵌套富余约 8 KiB；代价是 ~505 MiB PMM 池中的 512 KiB）。损坏的 #DF panic 横幅（&quot;andled&quot; -&gt; &quot;handled&quot;）也修复了。验证：确切崩溃的那块（wp10_tui 尾部 + ush SVC 轮，含经活动 HTTPS 的 checkupdate）现在跑到 &quot;12/12 checks passed&quot;，带真实 checkupdate 报告、无 panic。提交 4293e94。</td></tr><tr><td>O-02</td><td>内核</td><td>wait4 对 fork 的时序竞态抖动（2.1.0 遗留项）。2.1.0 时误诊为中断时序竞态；实际是<strong>确定性的</strong>簿记问题：进程死亡时，其子进程的 g_procs 条目仍保留 parent_tid = 死亡 tid；tid 释放并被复用后，新任务的 wait4(any-child) 收走了一个陈旧僵尸的退出码，并在自己的子进程被调度前返回（g6_exec_a 打印 &quot;child status = 142&quot; = 128+SIGSEGV，来自 pf_test 被 #PF 击杀、无人 wait 的子进程，判决跑在子进程首次输出之前）。修复前在同启动马拉松和新鲜启动（僵尸源排在受害者之前）中都复现（2/2 次启动）。</td><td>user_process_reap_resources 中的孤儿脱钩（每个仍指向死亡 tid 的条目 -&gt; 哨兵 -1，任何任务都无法认领），加上 sys_fork 的半成品尸体路径（地址空间复制失败 / 任务创建失败）同样脱钩——活着的父进程永不收走 POSIX 说从未创建的孩子。验证：新鲜启动测试组 20/20 次启动全 CLEAN（修复前 2/2 命中异常）；同启动马拉松 g6_exec_a 两轮都 = 138；同启动压力（僵尸源 + wait4 家族 x 8 轮 = 80 次运行）零异常，8/8 状态 138。提交 11d2127。</td></tr></tbody></table><h2 id="遗留问题" tabindex="-1">遗留问题 <a class="header-anchor" href="#遗留问题" aria-label="Permalink to &quot;遗留问题&quot;">​</a></h2><p>下表是 WP-07 收尾时声明的三项已知限制（每行：现象 / 影响 范围 / 当前处置 / 后续归属）。三项都不是 WP-07 引入的回归， 均为收尾时如实申报，构成 3.0.0 恢复生命周期的诚实边界。</p><table tabindex="0"><thead><tr><th>#</th><th>现象</th><th>影响范围</th><th>当前处置</th><th>后续归属</th></tr></thead><tbody><tr><td>K-01</td><td><code>make test</code> 中 19 个宿主侧单测程序构建失败（该单测组早于 3.0.0 目录重构，相关程序仍引用重构前的路径与头文件）。</td><td>仅宿主侧单测。内核、全部 L1 应用、六套件运行时矩阵（31/31）、dhtest、SSH E2E、HTTPS E2E 均不受影响且全绿。</td><td>接受为基线遗留——如实申报，未静默跳过。CI 实际强制的发布门禁（编译 0 错误 0 警告、六套件运行时矩阵、L1 每应用记录）不含 <code>make test</code>。</td><td>后续工作包按当前目录布局刷新宿主单测组；在此之前回归权重由运行时套件承担。</td></tr><tr><td>K-02</td><td>挂接 i6300ESB PCI 看门狗设备时，UEFI（OVMF）下 OCBL 载荷路径在槽位扫描后停止；对未修改的 WP07 前加载器的对照重构建以字节一致的方式复现，说明该缺陷早于 WP-07。</td><td>仅 UEFI 看门狗链路。不挂该设备时整条 UEFI 监控路径已实测验证；BIOS 形态承载完整且经过验证的看门狗机制（菜单空闲复位、挂死判定、判定失败的计数、[R]/[C] 与 [W]/[R]/[C] 接管菜单）。</td><td>接受为已知平台限制：BIOS 链路必须全通（实际全通）；不带 i6300ESB 的 UEFI 引导已验证并受支持。</td><td>后续工作包排查 OCBL-EFI 与 i6300ESB 的共存问题（UEFI BlockIo/固件服务与 PCI 看门狗的交互）。</td></tr><tr><td>K-03</td><td>更新站 CDN 可能继续按旧资产文件名提供缓存副本，导致客户端在发布后一段时间内拉取新改名的清单/资产时收到 404。</td><td>仅 OTA 客户端，且仅发生在改名后的缓存传播窗口内。</td><td>双命名兜底：每个改名的资产同时发布旧、新两个文件名变体，OTA 拉取无论命中缓存名还是传播名都能成功。</td><td>今后避免改名；双命名兜底在旧 CDN 副本可能仍被使用的期间持续保留。</td></tr></tbody></table><p>更早的边界申报（已关闭或已被取代）保留如下备查。WP-02 声明的诚实边界（OCIRE 内嵌的 OCOS 侧未实现：无 oc.* 事实 解析、无 SIGNAL_OK、无看门狗解除、无代理通道）已由 WP-03 G4 关闭（<code>src/L0/services/ocembed/</code>，监督测试组 3/3 在 <code>evidence/3_0_0_wp03_g4_ocembed/</code>）。WP-03 之后声明的限制 （设计使然，非缺陷）：</p><ul><li>ush 的 <code>kill</code> 在对 ocire_guard 代理的 kill 被拒绝时报告 &quot;no such process&quot;——syscall ABI 只携带单一 错误码，所以拒绝文本是泛化的；真实原因在内核日志里 （klog WARN &quot;kill refused: ocire_guard process&quot;）。</li><li>G5 之前裸的 <code>sti;hlt</code> 驻留仍留在四条已证实的路径中 （sys_read 的键盘等待、wp8cd 的前台等待、sdhci 的定时 等待、OTA 安顿循环）：它可能导致的被抢占停机冻结已为 电源睡眠修复（定时器回调 + 阻塞），且在那四条路径上从未 观测到；真正的定时阻塞唤醒原语是未来的调度器工作。</li><li>直接启动的 GRUB 条目（&quot;Open Cube OS (direct boot)&quot;）不携带 oc.* 事实：按定义直接启动不受监督（无信号、 无保护）——监督者条目是唯一受监督的路径。</li></ul><h2 id="_3-0-0-wp06g2-注记" tabindex="-1">3.0.0-WP06g2 注记 <a class="header-anchor" href="#_3-0-0-wp06g2-注记" aria-label="Permalink to &quot;3.0.0-WP06g2 注记&quot;">​</a></h2><p>WP06g1 收尾的 &quot;make all 不重建 userprogs&quot; 缺口 （06g1 的 catch-2）由 WP06g2 关闭：<code>src/L0/core/userprogs_data.h</code> 现在是真正的 make 目标（任何比该头新的 L1 源、i18n 资源或 生成器脚本都会重新生成它；<code>make all</code> 和 <code>make iso</code> 都携带该前置条件；发射是幂等的——写前逐字节比较，未变时 保留 mtime）。双向实测验证：一个打标的应用经 <code>make all</code> 进入 ISO，与全新构建逐字节一致；撤销打标则重新生成原始 的头。</p><p>声明的 WP06g2 边界（诚实限度，非缺陷）：</p><ul><li>L0 诊断/测试类服务体（*_test 和 wp 风格 程序的捕获输出）保留英文技术文本；面向用户的句子类 （文件工具的 usage/错误/描述、注册表提示、编辑器、IME、 shell）经 i18n 资源双语化。列头与状态 词刻意保持英文（zh_CN locale 约定——CJK 宽度会破坏对齐）。</li><li>OCSE 安装向导的 GUI 文本在 WP-06c 时就已双语 （它自己的词典）；TUI 桌面页面本批仍为英文。</li><li>IME 词库是 622 个手工编写的高频词；单字一如既往覆盖全部 3755 个一级汉字。</li></ul><p>WP06g2 交付修复附记（收尾之后，同批）：</p><ul><li><p>收尾推送从未达到绿 CI：词库 生成器 import 了 pypinyin，而干净的 CI 环境（按设计无 pip 包）在 ISO 步骤以 ModuleNotFoundError 失败。 生成器现在自包含——拼音从 pinyin_data.c 自己的 单字表合成（引擎自身匹配的那些音节），十个多音字词在 清单中携带其词典读音作为显式对；发射的 表与 pypinyin 构建的逐字节一致。拼写错误的 显式对无法通过合法音节分解检查。</p></li><li><p>wp06g1 站点携带的 site-data.js 在 dev 块后有一个多余的 <code>},</code>——一个 SyntaxError，window.SITE_DATA 从未加载， app.js 填充层（统计、下载卡片、历史表）自 wp06g1 起静默 跑在静态 HTML 回退上。结构已修复、数据同趟更正：稳定线 重新是 2.2.0/316（收尾曾把里程碑推进 稳定槽位，那会让 OTA 频道指向一个从未上传的 包），dev 块携带真实的 WP06g2 数对（build 403）。</p></li><li><p>WP06g3 更正——过去写在这里的 &quot;branches: ain]&quot; 条目是 幻影。字节级审计（对 fef5f41、0226e8c 和 HEAD 逐字节 od -c）显示工作流过滤器自文件创建之日起就一直是 <code>branches: [main]</code>；&quot;ain]&quot; 的读法是终端誊录伪影 （shell 输出显示层把字面 &#39;[m&#39; 当作 ANSI SGR 复位序列吃掉），从来不是真实笔误。工作流从未 需要改动；该条目退役。</p></li><li><p>tools/run_fix4_regression.py（v2.x 时代的 28 项测试组）断言 旧启动流（<code>oc&gt;</code> L0 恢复 shell 提示符、v1.0.0 横幅、&quot;233 commands&quot;）——主 ISO 许多个批次以来直接启动进 L1 shell（<code>ush&gt;</code>），测试组无法按原样通过，发布 SOP 不带 --deep 运行。它需要断言刷新；wp06g3 测试组（serial_enc、 ocse_enc、editor_rework、ocire_menu、install_ocire）和 https e2e 7/7 扛起了本批的回归重担。</p></li></ul><h2 id="k-06-wp-tui-input-encoding-hardening-4-6-扩展排查-引导服务存活期间" tabindex="-1">K-06（WP-tui-input-encoding-hardening 4.6 扩展排查）：引导服务存活期间 <a class="header-anchor" href="#k-06-wp-tui-input-encoding-hardening-4-6-扩展排查-引导服务存活期间" aria-label="Permalink to &quot;K-06（WP-tui-input-encoding-hardening 4.6 扩展排查）：引导服务存活期间&quot;">​</a></h2><p>OVMF 下的 OCBL 菜单无法通过键盘操作</p><ul><li>症状（两次诊断构建实测）：OCBL-EFI 菜单倒计时期间 <code>ReadKeyStroke</code> 从不返回按键——串口字节没有（OVMF 的终端驱动按 自身定时器抽干 16550 RBR，被消费的字节不再经 ConIn 回流），PS/2 按键同样没有（QEMU <code>sendkey</code> 在 10 秒窗口内同样饿死）。菜单因此总在 10 秒倒计时后自动引导默认条目。</li><li>根因：位于 OVMF/QEMU 固件事件交互之内——一个从不进入 <code>WaitForEvent</code> 的轮询式 UEFI 应用在该环境下得不到驱动进展。并非 OCBL 轮询代码缺陷：16550 是直读的（与串口输出同一契约），ConIn 侧 对 &#39;A&#39;/&#39;B&#39;/CR 导航键的接纳仍保留在代码中（若某固件将来回流被窃 字节即可生效）。</li><li>影响：OVMF 下菜单在显示期间无法通过输入设备选择引导条目。BIOS 侧菜单键盘操作完整可用（4.6 修复 int-14h 之后的串口 + PS/2）。</li><li>规避：默认条目即操作系统（倒计时直接引导）；独立 OCIRE ISO 默认 引导 OCIRE；两个载荷 shell（ExitBootServices 之后由内核自有驱动 服务）的串口 + PS/2 输入完全正常——4.2 六路径空格矩阵全绿（含两 个 UEFI 格）。</li><li>候选后续修复：基于 <code>WaitForEvent</code> 的菜单等待循环（倒计时期间驱动 固件事件系统）。超出本包范围，在此登记。</li></ul><h2 id="k-07-uefi-轨不再扫描非引导磁盘-wp-runtime-hardening" tabindex="-1">K-07 UEFI 轨不再扫描非引导磁盘（WP-runtime-hardening） <a class="header-anchor" href="#k-07-uefi-轨不再扫描非引导磁盘-wp-runtime-hardening" aria-label="Permalink to &quot;K-07 UEFI 轨不再扫描非引导磁盘（WP-runtime-hardening）&quot;">​</a></h2><p>OCRMECL 的 post-EBS 架构下，OCBL 的唯一磁盘后端是引导介质的 RAM 副本：多盘扫描、 A/B 槽位引导与外部 loader 链式加载在 UEFI 轨不可用（BIOS 轨不受影响）。修复方向： 在 OCRMECL 中增加磁盘驱动（AHCI/NVMe/virtio），属后续工作包。</p><h2 id="k-08-wp-compat-and-security-hardening-已在-wp-severe-fix-and-closure" tabindex="-1">K-08（WP-compat-and-security-hardening）：已在 WP-severe-fix-and-closure <a class="header-anchor" href="#k-08-wp-compat-and-security-hardening-已在-wp-severe-fix-and-closure" aria-label="Permalink to &quot;K-08（WP-compat-and-security-hardening）：已在 WP-severe-fix-and-closure&quot;">​</a></h2><p>以构造性方式关闭——横幅竞态的根因是 pid 注册窗口</p><ul><li>已关闭：根因定位 + 三层防御修复；连续 20 次启动横幅均为真实版本串、 <code>uname -r</code> 精确、<code>uname -a</code> 完整、零 panic（验收组在默认启动画面 模式下运行——即竞态的主场）。</li><li>根因（monitor hunter + 2.7 GB 中断 trace 实况捕获）： <code>l1_launcher_boot_default()</code> 在 <code>user_process_create()</code> 返回并 <code>boot_state_advance()</code> 打印之后才注册 <code>g_l1_entry_pid</code>，而 launcher 内核线程此时已就绪——该窗口内一次定时器抢占使 ush 在 pid 存在 之前跑到首个系统调用，L1_READY 一次性钩子的 pid 比对失败， <code>boot_splash_finish()</code> 从未执行，仍安装着的 splash 钩子（抑制 控制台输出）吞掉了整个横幅与首个提示符，而 ush 本体健康地在 getch 自旋等待。</li><li>修复分层：(1) 根因层——创建 + 注册收进同一段关中断窗口（本单 CPU 设计中定时器 IRQ 是唯一抢占源），失败启动路径也会拆除 splash； (2) 第二道防线——<code>g_l1_entry_pid==0</code> 期间任意 pid 的首个系统调用 都触发一次性钩子（默认入口是引导时唯一的环 3 进程）；(3) 症状层 ——uname 操作（L1SVC_DISP_UNAME）改为与 LANG_GET 同形的纯缓冲填充 （字节同形，横幅路径不再有 kcap 控制台捕获；交互式 <code>uname</code>/<code>-r</code>/<code>-a</code> 行为不变）。</li><li>证据：evidence/wp-severe-fix-and-closure/b-k08-uname-race.md <ul><li>猎捕 transcript。</li></ul></li></ul><h2 id="k-09-wp-severe-fix-and-closure-以-误诊-关闭——网络栈是健康的" tabindex="-1">K-09（WP-severe-fix-and-closure）：以&quot;误诊&quot;关闭——网络栈是健康的， <a class="header-anchor" href="#k-09-wp-severe-fix-and-closure-以-误诊-关闭——网络栈是健康的" aria-label="Permalink to &quot;K-09（WP-severe-fix-and-closure）：以&quot;误诊&quot;关闭——网络栈是健康的，&quot;">​</a></h2><p>不健康的是测试台架。入站 SSH 尚余一条诚实边界。</p><ul><li>已关闭（原结论被计数器推翻）：WP-compat 条目把 HTTPS/SSH E2E 失败 归咎&quot;沙箱网络&quot;。WP-severe-fix-and-closure 的猎捕用内核自身计数器 （netstat：DHCP 已服务、ARP 已解析、ICMP 4/4、TCP 正常、一个明文 HTTP 下载已保存）加一次真实 TLS 1.2 会话证明了相反结论。真实缺陷： (1) 一次性 TLS 测试服务器死于内核 TLS1.3 优先的 hello（RFC 7507 回退重连撞上已死监听者）；(2) <code>-serial mon:stdio</code> 台架通道在本沙箱 可测地饿死 QEMU 主循环（unix-socket 串口下同一 ISO ping 4/4）； (3) 陈旧提示符匹配把下一条命令射进仍在执行的命令里，暴露出 (4) 真实内核缺陷：COM1 RX 边沿丢失窗口（8259 边沿触发下 16550 电平保持的 INTR 可把粘贴的长命令行永远滞留 FIFO）——已用 10 ms tick 兜底 RX 轮询修复。HTTPS E2E 现在 8/8；SSH E2E 出站场景通过 （ssh-auth + ssh-exec）。</li><li>余留（诚实边界）：SSH 入站场景（宿主 paramiko 客户端 -&gt; 客内 sshd 经 hostfwd）仍存在时序相关的滞留——已有完整 pcap、滞留连接 monitor 转储（rtx_len==0、窗口开放、ESTABLISHED、客侧 KEXINIT 从未上线）与新增 netstat TX-errors 计数器（为零——驱动从未见失败 帧）证据。已落防线：超队列 ACK 不再静默丢弃发送队列，net_poll 为已接受未发送数据加了每轮冲刷助推。</li><li>证据：evidence/wp-severe-fix-and-closure/b-k09-e2e-network.md。</li></ul><h2 id="k-10-wp-compat-and-security-hardening-已在-wp-severe-fix-and-closure" tabindex="-1">K-10（WP-compat-and-security-hardening）：已在 WP-severe-fix-and-closure <a class="header-anchor" href="#k-10-wp-compat-and-security-hardening-已在-wp-severe-fix-and-closure" aria-label="Permalink to &quot;K-10（WP-compat-and-security-hardening）：已在 WP-severe-fix-and-closure&quot;">​</a></h2><p>关闭——单字符 &#39;!&#39; 之死是入口后放错了 PE</p><ul><li>已关闭：全部三个 UEFI 场景（shell/shutdown/reboot）转绿——OCIRE 测试组 14/14，为该测试组存在以来首次（七个 UEFI 场景全绿： shell:help/unknown/backspace、shutdown:notice/qemu-exit、 reboot:notice/qemu-exit）。</li><li>根因：每个 UEFI 场景都在 OVMF 分发之后随即死亡，串口线上只有单个 &#39;!&#39;——那是 OCBL <code>ocbl_raw_entry</code> 的 ABI 违例标记（handoff 魔数比对 失败），因为 <code>tools/build_ocire_iso.sh</code> 把 <code>build/ocbl/ocbl_x64.efi</code> （入口 RVA 是 post-EBS 裸入口，期待 RCX=handoff / RDX=OCR_UEFI_HANDOFF_MAGIC）直接当作 BOOTX64.EFI 摆放——OVMF 的 StartImage 以 EFI ABI（RCX=镜像句柄、RDX=系统表）到达，轨道在入口 即死。主 ISO 从无此问题（其 BOOTX64.EFI 是 OCRMECL PE）；恢复盘 ISO 还停留在 pre-OCRMECL 布局。</li><li>修复：恢复盘 ISO 现在摆放主 ISO 的链条（BOOTX64.EFI = ocrmecl_x64.efi、/OCBL.EFI = ocbl_x64.efi、El Torito = OCRMECL 复合镜像）；G13 封印不变。</li><li>旧结论&quot;UEFI 引导路径需要独立工作包&quot;是错的——它需要的只是入口后 放对 PE。</li><li>证据：evidence/wp-severe-fix-and-closure/b-k10-ocire-uefi.md + build/ocire/test-*.log。</li></ul>',31)])])}const _=e(i,[["render",r]]);export{p as __pageData,_ as default};
